sys_script_include.script:
var IoTStreamingGateway = Class.create();
IoTStreamingGateway.prototype = {
    initialize: function() {
        this.THRESHOLDS = {
            temperature:       { warning: 70.0, critical: 85.0, unit: '°C' },
            vibration:         { warning: 4.5,  critical: 7.5,  unit: 'mm/s' },
            power_consumption: { warning: 85.0, critical: 95.0, unit: '%' }
        };
        this.MACHINE_TABLE = 'x_2056099_indust_0_machine';
        this.ALERT_TABLE = 'x_2056099_indust_0_inv_alert';
    },

    /**
     * Ingest a live telemetry payload from an IoT gateway or edge device.
     * @param {object} payload - { device_id, temperature, vibration, power_consumption, notes }
     * @returns {object} { success, machine_sys_id, alerts_generated, machine_status }
     */
    ingest: function(payload) {
        if (!payload) {
            return { success: false, error: 'Telemetry payload is required' };
        }

        var devId = payload.device_id || payload.machine_id || payload.name;
        if (!devId) {
            return { success: false, error: 'device_id or machine_id is required' };
        }

        // 1. Locate machine record
        var machGr = new GlideRecord(this.MACHINE_TABLE);
        machGr.addQuery('serial_number', devId);
        machGr.setLimit(1);
        machGr.query();

        if (!machGr.next()) {
            // [HackNow critical features] also accept the machine number
            machGr = new GlideRecord(this.MACHINE_TABLE);
            machGr.addQuery('number', devId).addOrCondition('name', 'CONTAINS', devId);
            machGr.setLimit(1);
            machGr.query();
            if (!machGr.next()) {
                return { success: false, error: 'Machine not found for identifier: ' + devId };
            }
        }

        var machSysId = machGr.getUniqueValue();
        var machName = machGr.getValue('name') || devId;

        // 2. Check thresholds and compile alerts
        var alerts = this._checkThresholds(machGr, payload);

        // 3. Update machine state and condition
        var condition = 'good';
        if (alerts.some(function(a) { return a.severity === 'critical'; })) {
            condition = 'critical';
        } else if (alerts.length > 0) {
            condition = 'fair';
        }

        machGr.setValue('machine_condition', condition);
        var telemetrySummary = '[IoT Live ' + new GlideDateTime().getValue() + '] ' +
            'Temp: ' + (payload.temperature != null ? payload.temperature + '°C' : 'N/A') + ', ' +
            'Vib: ' + (payload.vibration != null ? payload.vibration + 'mm/s' : 'N/A') + ', ' +
            'Power: ' + (payload.power_consumption != null ? payload.power_consumption + '%' : 'N/A');

        var prevNotes = machGr.getValue('notes') || '';
        machGr.setValue('notes', (telemetrySummary + '\n' + prevNotes.substring(0, 1000)).trim());
        // critical temperature/vibration is treated as a breakdown: the existing flow opens downtime + maintenance,
        // and the machine rule proposes rescheduling of the affected orders
        var wasRunning = ['broken_down', 'under_maintenance', 'out_of_service', 'retired', 'decommissioned'].indexOf(machGr.getValue('status')) === -1;
        var breakdown = wasRunning && alerts.some(function(a) { return a.severity === 'critical' && a.metric !== 'power_consumption'; });
        if (breakdown) machGr.setValue('status', 'broken_down');
        machGr.update();
        var risk = breakdown ? 'BREAKDOWN' : this._maintenanceRisk(machGr, alerts);

        return {
            success: true,
            machine_status: machGr.getValue('status'),
            maintenance_risk: risk,
            machine_sys_id: machSysId,
            machine_name: machName,
            machine_condition: condition,
            telemetry: payload,
            alerts_generated: alerts.length,
            alerts: alerts
        };
    },

    /**
     * Simulates live IoT telemetry across all production floor machines.
     * Useful for live demonstrations, hackathon judging, and digital twin testing.
     * @returns {object} Summary of simulated readings
     */
    simulateAllMachines: function() {
        var machGr = new GlideRecord(this.MACHINE_TABLE);
        machGr.addQuery('active', true);
        machGr.query();

        var readings = [];
        var totalAlerts = 0;

        while (machGr.next()) {
            var status = machGr.getValue('status') || 'operational';
            var isOperational = status === 'operational' || status === 'available';

            // Generate realistic values
            var baseTemp = isOperational ? 58.0 : 35.0;
            var temp = Math.round((baseTemp + (Math.random() * 28.0)) * 10.0) / 10.0;
            var vib = Math.round((1.2 + (Math.random() * 6.5)) * 10.0) / 10.0;
            var pwr = Math.round((isOperational ? 60.0 + (Math.random() * 38.0) : 10.0) * 10.0) / 10.0;

            var payload = {
                device_id: machGr.getValue('name'),
                temperature: temp,
                vibration: vib,
                power_consumption: pwr
            };

            var ingestRes = this.ingest(payload);
            if (ingestRes.success) {
                readings.push(ingestRes);
                totalAlerts += ingestRes.alerts_generated;
            }
        }

        return {
            success: true,
            machines_polled: readings.length,
            total_alerts_generated: totalAlerts,
            timestamp: new GlideDateTime().getValue(),
            readings: readings
        };
    },

    _checkThresholds: function(machGr, payload) {
        var alerts = [];
        var checks = [
            { field: 'temperature', val: payload.temperature },
            { field: 'vibration', val: payload.vibration },
            { field: 'power_consumption', val: payload.power_consumption }
        ];

        for (var i = 0; i < checks.length; i++) {
            var c = checks[i];
            if (c.val == null) continue;
            var th = this.THRESHOLDS[c.field];
            if (!th) continue;

            var sev = null;
            if (c.val >= th.critical) {
                sev = 'critical';
            } else if (c.val >= th.warning) {
                sev = 'warning';
            }

            if (sev) {
                var alertId = this._createAlert(machGr, c.field, c.val, th[sev], th.unit, sev);
                alerts.push({
                    metric: c.field,
                    measured_value: c.val,
                    threshold: th[sev],
                    severity: sev,
                    alert_sys_id: alertId
                });
            }
        }
        return alerts;
    },

    _createAlert: function(machGr, metric, value, threshold, unit, severity) {
        try {
            var altGr = new GlideRecord(this.ALERT_TABLE);
            altGr.newRecord();
            altGr.setValue('alert_type', 'machine_threshold');
            altGr.setValue('severity', severity === 'critical' ? 'critical' : 'high');
            altGr.setValue('status', 'open');
            altGr.setValue('related_machine', machGr.getUniqueValue());
            altGr.setValue('alert_date', new GlideDateTime().getValue());
            altGr.setValue('alert_message', '[IoT Anomaly] ' + machGr.getValue('name') + ' ' +
                           metric + ' reached ' + value + unit + ' exceeding ' + severity + ' threshold of ' + threshold + unit);
            return altGr.insert();
        } catch (e) {
            gs.warn('IoTStreamingGateway _createAlert error: ' + e.message);
            return null;
        }
    },

    /**
     * Rule-based early warning (no ML): three or more threshold breaches on the same machine within 24 hours
     * mean maintenance risk HIGH -> one open predictive-maintenance alert and an earlier next maintenance date.
     */
    _maintenanceRisk: function(machGr, alerts) {
        var since = new GlideDateTime(); since.addDaysUTC(-1);
        var ga = new GlideAggregate(this.ALERT_TABLE);
        ga.addQuery('related_machine', machGr.getUniqueValue());
        ga.addQuery('alert_type', 'machine_threshold');
        ga.addQuery('alert_message', 'STARTSWITH', '[IoT Anomaly]');
        ga.addQuery('sys_created_on', '>=', since.getValue());
        ga.addAggregate('COUNT');
        ga.query();
        var breaches = ga.next() ? parseInt(ga.getAggregate('COUNT'), 10) || 0 : 0;
        if (breaches < 3) return breaches > 0 ? 'ELEVATED' : 'NORMAL';
        var open = new GlideRecord(this.ALERT_TABLE);
        open.addQuery('related_machine', machGr.getUniqueValue());
        open.addQuery('alert_message', 'STARTSWITH', '[Predictive Maintenance]');
        open.addQuery('status', 'NOT IN', 'resolved,dismissed');
        open.setLimit(1);
        open.query();
        if (!open.hasNext()) {
            var al = new GlideRecord(this.ALERT_TABLE);
            al.newRecord();
            al.setValue('alert_type', 'machine_threshold');
            al.setValue('severity', 'high');
            al.setValue('status', 'open');
            al.setValue('related_machine', machGr.getUniqueValue());
            al.setValue('alert_date', new GlideDateTime().getValue());
            al.setValue('alert_message', '[Predictive Maintenance] ' + machGr.getValue('name') + ': ' + breaches +
                ' threshold breaches in the last 24 hours. Maintenance risk HIGH - schedule preventive maintenance before failure.');
            al.insert();
            var soon = new GlideDateTime(); soon.addDaysUTC(1);
            machGr.setValue('next_scheduled_maint', soon.getValue());
            machGr.update();
        }
        return 'HIGH';
    },

    type: 'IoTStreamingGateway'
};
